"""OBSOLETE (7 Oct 2026): Experiment 3 (text generated by Claude Haiku 4.5) was removed from the paper; kept for the record, not run by run_all.sh.
Experiment 3: LLM-generated text on both sides (Z real post; X comment; Y0/Y1 summaries).

Phases:
  compute -> embeddings, sentiment scores A, B (the paper's X, Y), full-sample tests (exp3_llm_full_sample_raw.csv) and
             subsample tests (exp3_llm_subsample_raw.csv)
  plots   -> exp3_llm_typeI.pdf, exp3_llm_rv.pdf and summary_exp3.json, recomputed from the raw
             files with the current robust-test calibration and RV_alpha
Primary regressor RidgeCV throughout (since 30 Sept 2026: with n <= 3000 and d >= 384 no configuration of this experiment
meets the least squares rule of citext.estimators); kernel ridge (RBF, median heuristic) as secondary. Before 29 Sept 2026
the primary was kernel ridge, and on 29 Sept the least-squares-or-ridge rule.

usage: python experiments/exp3_llm.py PATH_TO_JSONL [N_SUBSAMPLES] [--only compute,plots]
"""
from __future__ import annotations

import argparse
import hashlib
import json
import sys
import time
from pathlib import Path

import numpy as np
import pandas as pd
from joblib import Parallel, delayed
from scipy import stats
from sklearn.decomposition import PCA
from sklearn.linear_model import RidgeCV
from threadpoolctl import threadpool_limits

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from citext import plotting as P  # noqa: E402
from citext.estimators import benchmark_pair, crossfit_folds, gcm_test, robust_test, rv_alpha  # noqa: E402
from citext.llm_gen import PERSONAS, SYSTEM, X_INSTR, Y0_INSTR, Y1_INSTR  # noqa: E402
from citext.paths import RESULTS_DIR  # noqa: E402
from citext.text_semi import E1_NAME, E2_NAME, embed_texts  # noqa: E402

ALPHA = 0.05
PRIMARY, SECONDARY = "ridge", "krr"   # primary: ridge regression throughout (see the docstring); secondary: kernel ridge
N_SUB = [500, 1000, 2000]
N_JOBS = 5
LABEL_SCORE = {"POSITIVE": 1.0, "NEUTRAL": 0.0, "NEGATIVE": -1.0}
PSIS = ["E1", "E2", "E1+E2"]
BENCH_PARTNER = {"E1": "E2", "E2": "E1"}


def load_rows(path: Path):
    rows = [json.loads(l) for l in path.read_text().splitlines() if l.strip()]
    rows = [r for r in rows if r["X"] and r["Y0"] and r["Y1"]]
    rows.sort(key=lambda r: r["idx"])
    return rows


def embeddings(rows, key):
    h = hashlib.md5((key + str(len(rows)) + rows[0]["Z"][:50]).encode()).hexdigest()[:8]
    out = {}
    for field in ("Z", "X", "Y0", "Y1"):
        texts = [r[field] for r in rows]
        out[("E1", field)] = embed_texts(texts, E1_NAME, cache_key=f"llm{h}_{field}")
        out[("E2", field)] = embed_texts(texts, E2_NAME, cache_key=f"llm{h}_{field}")
    return out


def sentiment_axis(EX, s, EY0, EY1, K=5, seed=0):
    """Cross-fitted sentiment direction: ridge from E1(X) to the self-reported label score of X,
    applied to the held-out fold's X (giving A) and to its Y0, Y1 (giving B0, B1)."""
    A, B0, B1 = (np.empty(len(s)) for _ in range(3))
    for tr, te in crossfit_folds(len(s), K, seed):
        m = RidgeCV(alphas=np.logspace(-2, 4, 13)).fit(EX[tr], s[tr])
        A[te], B0[te], B1[te] = m.predict(EX[te]), m.predict(EY0[te]), m.predict(EY1[te])
    return A, B0, B1


def pc1_axis(EX, EY0, EY1, seed=0):
    A = PCA(1, random_state=seed).fit_transform(EX)[:, 0]
    pY = PCA(1, random_state=seed).fit(EY0)
    return A, pY.transform(EY0)[:, 0], pY.transform(EY1)[:, 0]


def sub_rep(A, B, Psi, n, seed, reg):
    with threadpool_limits(2):
        rng = np.random.default_rng(seed)
        idx = rng.choice(len(A), n, replace=False)
        r = gcm_test(A[idx], B[idx], Psi[idx], regressor=reg, seed=seed, alpha=ALPHA)
        return {"n": n, "seed": seed, "rho": r.rho_hat, "se": r.se}


def phase_compute(path: Path, n_subsamples: int):
    rows = load_rows(path)
    print(f"{len(rows)} rows from {path.name}", flush=True)
    emb = embeddings(rows, path.stem)
    s = np.array([LABEL_SCORE.get(r["X_label"], 0.0) for r in rows])
    axes_def = {"sentiment": sentiment_axis(emb[("E1", "X")], s, emb[("E1", "Y0")], emb[("E1", "Y1")]),
                "pc1": pc1_axis(emb[("E1", "X")], emb[("E1", "Y0")], emb[("E1", "Y1")])}
    A, B0, B1 = axes_def["sentiment"]
    meta = {"n_rows": len(rows), "labels": pd.Series([r["X_label"] for r in rows]).value_counts().to_dict(),
            "personas": pd.Series([r.get("persona", "") for r in rows]).value_counts().to_dict(),
            "sentiment_following": {"corr_label_B0": float(np.corrcoef(s, B0)[0, 1]), "corr_label_B1": float(np.corrcoef(s, B1)[0, 1]),
                                    "corr_A_B0": float(np.corrcoef(A, B0)[0, 1]), "corr_A_B1": float(np.corrcoef(A, B1)[0, 1])},
            "model": rows[0].get("model", "unknown")}
    print("meta:", json.dumps(meta), flush=True)
    (RESULTS_DIR / "exp3_llm_meta.json").write_text(json.dumps(meta, indent=1))
    psis = {"E1": emb[("E1", "Z")], "E2": emb[("E2", "Z")], "E1+E2": np.hstack([emb[("E1", "Z")], emb[("E2", "Z")]])}

    full = []
    for axis_name, (Ax, Bx0, Bx1) in axes_def.items():
        for hyp, Bx in (("H0", Bx0), ("H1", Bx1)):
            for psi_name, Psi in psis.items():
                for reg in (PRIMARY, SECONDARY):
                    r = gcm_test(Ax, Bx, Psi, regressor=reg, seed=0, alpha=ALPHA)
                    rec = {"axis": axis_name, "hyp": hyp, "psi": psi_name, "reg": reg, "n": len(Ax),
                           "rho_hat": r.rho_hat, "se": r.se, "pvalue": r.pvalue}
                    if psi_name in BENCH_PARTNER:
                        b = benchmark_pair(Ax, Bx, Psi, psis[BENCH_PARTNER[psi_name]], regressor=reg, seed=0)
                        rec.update({"bench": b["bench"], "bench_r2_A": b["r2_A"], "bench_r2_B": b["r2_B"], "bench_partner": BENCH_PARTNER[psi_name]})
                    full.append(rec)
                    print(f"  {axis_name} {hyp} psi={psi_name} {reg}: rho={r.rho_hat:.3f} se={r.se:.3f} p={r.pvalue:.3g} bench={rec.get('bench', float('nan')):.3f}", flush=True)
    pd.DataFrame(full).to_csv(RESULTS_DIR / "exp3_llm_full_sample_raw.csv", index=False)

    rows_sub = []
    for hyp, Bx in (("H0", B0), ("H1", B1)):
        for psi_name, Psi in psis.items():
            for n in N_SUB:
                t = time.time()
                res = Parallel(n_jobs=N_JOBS)(delayed(sub_rep)(A, Bx, Psi, n, sd, PRIMARY) for sd in range(n_subsamples))
                rows_sub += [{"axis": "sentiment", "hyp": hyp, "psi": psi_name, "reg": PRIMARY, **r} for r in res]
                print(f"  sub {hyp} {psi_name} n={n}: {time.time()-t:.0f}s", flush=True)
    pd.DataFrame(rows_sub).to_csv(RESULTS_DIR / "exp3_llm_subsample_raw.csv", index=False)

    ex = []
    for r in sorted(rows, key=lambda r: len(r["Z"]))[:40:13][:3]:
        ex.append(f"**Z:** {r['Z']}\n\n**X** [{r['X_label']}; persona: {r.get('persona','')}]: {r['X']}\n\n**Y0:** {r['Y0']}\n\n**Y1:** {r['Y1']}\n")
    (RESULTS_DIR / "exp3_examples.md").write_text("\n---\n".join(ex))


def phase_plots(path: Path):
    import matplotlib.pyplot as plt
    from matplotlib.lines import Line2D
    P.setup()
    dfF = pd.read_csv(RESULTS_DIR / "exp3_llm_full_sample_raw.csv")
    dfF["RV"] = np.abs(dfF.rho_hat)
    dfF["RV_alpha"] = [rv_alpha(r, s, ALPHA) for r, s in zip(dfF.rho_hat, dfF.se)]
    dfF["reject"] = np.abs(dfF.rho_hat) > stats.norm.ppf(1 - ALPHA / 2) * dfF.se
    dfF["robust_bench_reject"] = [robust_test(r, s, b, ALPHA)["reject"] if b == b else np.nan for r, s, b in zip(dfF.rho_hat, dfF.se, dfF.get("bench", np.nan))]
    dfF.to_csv(RESULTS_DIR / "exp3_llm_full_sample.csv", index=False)

    dfS = pd.read_csv(RESULTS_DIR / "exp3_llm_subsample_raw.csv")
    dfS["reject"] = (np.abs(dfS.rho) > stats.norm.ppf(1 - ALPHA / 2) * dfS.se).astype(float)
    bench_full = {(h, p): float(dfF[(dfF.axis == "sentiment") & (dfF.hyp == h) & (dfF.psi == p) & (dfF.reg == PRIMARY)].bench.iloc[0])
                  for h in ("H0", "H1") for p in BENCH_PARTNER}
    dfS["robust_bench"] = [robust_test(r, s, bench_full[(h, p)], ALPHA)["reject"] if (h, p) in bench_full else np.nan
                           for r, s, h, p in zip(dfS.rho, dfS.se, dfS.hyp, dfS.psi)]
    dfS.to_csv(RESULTS_DIR / "exp3_llm_subsample_decisions.csv", index=False)
    aggS = dfS.groupby(["hyp", "psi", "n"]).agg(rej=("reject", "mean"), rej_robust=("robust_bench", "mean"), rho=("rho", "mean"), nsub=("seed", "count")).reset_index()
    aggS.to_csv(RESULTS_DIR / "exp3_llm_subsample.csv", index=False)

    # ---- rejection rate vs n under H0 and H1
    fig, axs = plt.subplots(1, 2, figsize=P.DOUBLE, sharey=True)
    cols = {"E1": P.CAT[0], "E2": P.CAT[1], "E1+E2": P.CAT[2]}
    labs = {"E1": r"$\psi=E_1(Z)$", "E2": r"$\psi=E_2(Z)$", "E1+E2": r"$\psi=[E_1,E_2](Z)$"}
    for ax, hyp, title in zip(axs, ("H0", "H1"), (r"$H_0$: $Y$ generated from $Z$ alone", r"$H_1$: $Y$ matches the sentiment of $X$")):
        for psi_name in PSIS:
            a = aggS[(aggS.hyp == hyp) & (aggS.psi == psi_name)].sort_values("n")
            ax.plot(a.n, a.rej, marker="o", color=cols[psi_name], label=labs[psi_name])
        ax.axhline(ALPHA, color=P.MUTED, linewidth=0.8, linestyle="--", zorder=1)
        ax.set_xscale("log")
        ax.set_xticks(N_SUB)
        ax.set_xticklabels([str(n) for n in N_SUB])
        ax.minorticks_off()
        ax.set_xlabel(r"subsample size $n$")
        ax.set_title(title)
        ax.set_ylim(-0.02, 1.02)
    axs[0].set_ylabel("rejection rate (standard test)")
    axs[0].legend(loc="upper left")
    P.savefig(fig, "exp3_llm_typeI.pdf")

    # ---- RV, RV_alpha and benchmarks on the full sample (sentiment axis, primary regressor)
    d = dfF[(dfF.axis == "sentiment") & (dfF.reg == PRIMARY)]
    fig, ax = plt.subplots(figsize=P.SINGLE)
    order = [("H0", "E1"), ("H0", "E2"), ("H0", "E1+E2"), ("H1", "E1"), ("H1", "E2"), ("H1", "E1+E2")]
    xs = np.arange(len(order), dtype=float)
    xs[3:] += 0.6
    for x, (hyp, psi_name) in zip(xs, order):
        r = d[(d.hyp == hyp) & (d.psi == psi_name)].iloc[0]
        ax.errorbar(x, r.RV, yerr=1.96 * r.se, fmt="o", color=P.CAT[0], ecolor=P.CAT[0], elinewidth=1, capsize=2, markersize=5, zorder=3)
        ax.plot([x], [r.RV_alpha], marker="v", linestyle="none", color=P.SEQ[700], markerfacecolor=P.SEQ[700],
                markeredgecolor="white", markersize=5.5, markeredgewidth=0.9, zorder=5)
        if r.get("bench", np.nan) == r.get("bench", np.nan):
            ax.plot([x], [r.bench], marker="s", color=P.CAT[1], markersize=5, zorder=3)
    ax.set_xticks(xs)
    short = {"E1": r"$E_1$", "E2": r"$E_2$", "E1+E2": r"$[E_1,E_2]$"}
    ax.set_xticklabels([f"{h}\n{short[p]}" for h, p in order], fontsize=6.5)
    ax.set_ylabel("robustness value")
    ax.set_ylim(0, None)
    handles = [Line2D([], [], marker="o", color=P.CAT[0], linestyle="none", label=r"$\mathrm{RV}=|\hat\rho|$ ($\pm 1.96$ se)"),
               Line2D([], [], marker="v", color=P.SEQ[700], markerfacecolor=P.SEQ[700], markeredgecolor="white",
                      linestyle="none", markersize=5.5, markeredgewidth=0.9, label=r"$\mathrm{RV}_\alpha$"),
               Line2D([], [], marker="s", color=P.CAT[1], linestyle="none", label=r"benchmark $\hat\rho_{\mathrm{bench}}$")]
    ax.legend(handles=handles, loc="upper left")
    ax.grid(axis="x", visible=False)
    P.savefig(fig, "exp3_llm_rv.pdf")

    meta = json.loads((RESULTS_DIR / "exp3_llm_meta.json").read_text())
    usage_file = path.with_suffix(".usage.json")
    summary = {**meta, "temperature": "API default (1.0); the parameter is not sent", "max_tokens": 300,
               "prompts": {"system": SYSTEM, "X": X_INSTR, "Y0": Y0_INSTR, "Y1": Y1_INSTR, "personas": list(PERSONAS)},
               "primary_regressor": PRIMARY, "secondary_regressor": SECONDARY, "encoders": {"E1": E1_NAME, "E2": E2_NAME},
               "summary_axis": "cross-fitted ridge direction from E1(X) to the self-reported sentiment label of X, applied to E1(X) and E1(Y)",
               "subsample_sizes": N_SUB, "n_subsamples": int(dfS.groupby(["hyp", "psi", "n"]).size().min()),
               "usage": json.loads(usage_file.read_text()) if usage_file.exists() else None,
               "full_sample": dfF.to_dict(orient="records"), "subsample": aggS.to_dict(orient="records"),
               "figure_regressors": {"exp3_llm_typeI.pdf": PRIMARY, "exp3_llm_rv.pdf": PRIMARY}}
    (RESULTS_DIR / "summary_exp3.json").write_text(json.dumps(summary, indent=1, default=float))
    print("plots written", flush=True)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("path")
    ap.add_argument("n_subsamples", nargs="?", type=int, default=100)
    ap.add_argument("--only", default="compute,plots")
    args = ap.parse_args()
    t0 = time.time()
    phases = args.only.split(",")
    if "compute" in phases:
        phase_compute(Path(args.path), args.n_subsamples)
    if "plots" in phases:
        phase_plots(Path(args.path))
    print(f"done in {(time.time()-t0)/60:.1f} min")


if __name__ == "__main__":
    main()
